const exported={};new Function('exports',compiled)(exported)
const retain=exported.retainOracleCleanupObservation
const results=[]
for(const registration of ['static','dynamic'])for(const bodyThrows of [false,true])for(const cleanupThrows of [false,true]){
 const raw={rows:['wrong row'],cleanupErrors:['prior diagnostic']}
 const primary=Object.create(null),secondary={kind:'secondary'},last=undefined
 const calls=[];let owned=false
 const task=(name,reason)=>()=>{calls.push([name,owned]);if(cleanupThrows&&(name==='late1'||name==='late2'))throw reason}
 const tasks=registration==='static'?[task('late1',secondary),task('early'),task('late2',last)]:[task('early')]
 let result,failure,observed
 try{
  try{result=await retain(async()=>{
   owned=true
   if(registration==='dynamic')tasks.unshift(task('late1',secondary))
   await Promise.resolve()
   if(registration==='dynamic')tasks.push(task('late2',last))
   if(bodyThrows)throw primary
   return raw
  },tasks)}catch(error){observed=error}
  if(JSON.stringify(calls)!==JSON.stringify([['late1',true],['early',true],['late2',true]]))throw new Error('Missing/reordered acquired resource release: '+JSON.stringify(calls))
  if(bodyThrows){
   if(cleanupThrows){if(!(observed instanceof AggregateError)||observed.cause!==primary||observed.errors.length!==3||observed.errors[0]!==primary||observed.errors[1]!==secondary||observed.errors[2]!==last)throw new Error('Original primary or exact secondary identities lost')}
   else if(observed!==primary)throw new Error('Original primary identity lost')
  }else{
   if(observed!==undefined)throw new Error('Completed raw observation replaced by cleanup')
   if(result.rows!==raw.rows||raw.cleanupErrors.length!==1||result.cleanupErrors[0]!=='prior diagnostic')throw new Error('Raw/prior diagnostic identity lost')
   if(cleanupThrows){if(result.cleanupErrors.length!==3||result.cleanupErrors[1]!=='[object Object]'||result.cleanupErrors[2]!=='undefined')throw new Error('Dynamic cleanup diagnostics missing')}
   else if(result!==raw)throw new Error('Successful cleanup failed to return exact raw result')
  }
 }catch(error){failure=String(error)}
 results.push({registration,bodyThrows,cleanupThrows,verdict:failure?'FAIL':'PASS',...(failure?{failure}:{}),calls})
}
